#pragma material(Backend = ThinCustom, ShadingModel = "Unlit")
// `Backend = "Instance"` is the old name of ThinCustom.
/// @name DreamShaderTests/Migrate/M_MgBackend
export void M_MgBackend(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    Color = float3(1.0, 0.5, 0.25);
    Base.EmissiveColor = Color;
}
